/**
 * NewEra AI Agent — original cinematic score.
 *
 * The entire 2:04 score is synthesised from scratch with the Web Audio API and
 * rendered offline into a single AudioBuffer. Live playback and the offline WAV
 * export consume the exact same buffer, so picture and sound can never drift.
 *
 * Nothing here is sampled or borrowed: every sound is generated by oscillators,
 * noise and filters, and every random value comes from a seeded PRNG so a render
 * is bit-for-bit reproducible.
 */

export const SAMPLE_RATE = 44100;
export const DURATION = 124.0;

/* ------------------------------------------------------------------ *
 * Deterministic randomness
 * ------------------------------------------------------------------ */

/** Small, fast, seedable PRNG (mulberry32). */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* ------------------------------------------------------------------ *
 * Musical material
 * ------------------------------------------------------------------ */

const SEMITONE = { c: 0, 'c#': 1, d: 2, 'd#': 3, e: 4, f: 5, 'f#': 6, g: 7, 'g#': 8, a: 9, 'a#': 10, b: 11 };

/** Convert a scientific note name such as "a2" or "c#4" into hertz. */
export function noteFreq(name) {
  const match = /^([a-g]#?)(-?\d)$/.exec(String(name));
  if (!match) return 440;
  const midi = SEMITONE[match[1]] + (parseInt(match[2], 10) + 1) * 12;
  return 440 * Math.pow(2, (midi - 69) / 12);
}

/** A natural-minor pentatonic ladder — the motif the whole film grows from. */
export const MOTIF = ['a2', 'c3', 'd3', 'e3', 'g3', 'a3', 'c4', 'd4', 'e4', 'g4', 'a4', 'c5'];

/** Act boundaries, in seconds. Kept in one place so audio and picture agree. */
export const ACTS = [
  { id: 'cold', start: 0.0, end: 9.0 },
  { id: 'spark', start: 9.0, end: 27.0 },
  { id: 'grid', start: 27.0, end: 50.0 },
  { id: 'ascent', start: 50.0, end: 71.5 },
  { id: 'impact', start: 71.5, end: 74.0 },
  { id: 'hero', start: 74.0, end: 99.0 },
  { id: 'reveal', start: 99.0, end: 118.0 },
  { id: 'outro', start: 118.0, end: 124.0 }
];

/* ------------------------------------------------------------------ *
 * Voice primitives
 * ------------------------------------------------------------------ */

/**
 * Percussive/plucked amplitude envelope on a single AudioParam.
 * Times are absolute; the curve is exponential for a natural decay.
 */
function shape(param, t0, peak, attack, decay, hold = 0, release = 0.05) {
  const p = Math.max(0.0001, peak);
  param.cancelScheduledValues(t0);
  param.setValueAtTime(0.0001, t0);
  param.exponentialRampToValueAtTime(p, t0 + Math.max(0.001, attack));
  const sustainAt = t0 + attack + hold;
  if (hold > 0) param.setValueAtTime(p, sustainAt);
  param.exponentialRampToValueAtTime(0.0001, sustainAt + Math.max(0.02, decay));
  if (release > 0) param.setValueAtTime(0.0001, sustainAt + decay + release);
  return sustainAt + decay;
}

/** Build (and memoise) a mono noise buffer of the requested length. */
function noiseBuffer(ctx, seconds, rnd, cache) {
  const key = seconds.toFixed(2);
  if (cache.has(key)) return cache.get(key);
  const length = Math.max(1, Math.floor(ctx.sampleRate * seconds));
  const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
  const data = buffer.getChannelData(0);
  let last = 0;
  for (let i = 0; i < length; i += 1) {
    const white = rnd() * 2 - 1;
    last = (last + 0.02 * white) / 1.02; // slight low-pass: warmer, less hissy
    data[i] = white * 0.7 + last * 3.0;
  }
  cache.set(key, buffer);
  return buffer;
}

function makePanner(ctx, pan) {
  const panner = ctx.createStereoPanner();
  panner.pan.value = Math.max(-1, Math.min(1, pan));
  return panner;
}

/** A single filtered oscillator note with optional pitch glide. */
function tone(ctx, dest, opts) {
  const {
    t0, freq, dur = 1, type = 'sine', gain = 0.2, attack = 0.01,
    decay = dur, pan = 0, glideTo = 0, detune = 0, cutoff = 0, q = 0.7, hold = 0
  } = opts;
  const osc = ctx.createOscillator();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, t0);
  if (glideTo > 0) osc.frequency.exponentialRampToValueAtTime(glideTo, t0 + dur);
  if (detune) osc.detune.value = detune;
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain, attack, decay, hold);
  const panner = makePanner(ctx, pan);
  let node = osc;
  if (cutoff > 0) {
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(cutoff, t0);
    filter.frequency.exponentialRampToValueAtTime(Math.max(120, cutoff * 0.45), t0 + dur);
    filter.Q.value = q;
    osc.connect(filter);
    node = filter;
  }
  node.connect(amp);
  amp.connect(panner);
  panner.connect(dest);
  osc.start(t0);
  osc.stop(t0 + dur + 0.08);
}

/** Detuned saw stack — pads, strings and swells. */
function pad(ctx, dest, opts) {
  const { t0, freq, dur, gain = 0.12, attack = 1.2, release = 2.4, pan = 0, cutoff = 1400, spread = 8 } = opts;
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.linearRampToValueAtTime(gain, t0 + attack);
  amp.gain.setValueAtTime(gain, t0 + Math.max(attack, dur - release));
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + 0.1);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(cutoff * 0.55, t0);
  filter.frequency.linearRampToValueAtTime(cutoff, t0 + attack);
  filter.Q.value = 0.9;
  const panner = makePanner(ctx, pan);
  filter.connect(amp);
  amp.connect(panner);
  panner.connect(dest);
  const voices = [-spread, 0, spread];
  for (const detune of voices) {
    const osc = ctx.createOscillator();
    osc.type = 'sawtooth';
    osc.frequency.value = freq;
    osc.detune.value = detune;
    osc.connect(filter);
    osc.start(t0);
    osc.stop(t0 + dur + 0.2);
  }
}

/** Karplus-flavoured pluck: short noise burst into a resonant low-pass. */
function pluck(ctx, dest, opts, cache, rnd) {
  const { t0, freq, dur = 0.9, gain = 0.16, pan = 0, cutoff = 0 } = opts;
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, 0.12, rnd, cache);
  const filter = ctx.createBiquadFilter();
  filter.type = 'bandpass';
  filter.frequency.setValueAtTime(freq * 2.2, t0);
  filter.frequency.exponentialRampToValueAtTime(Math.max(120, freq * 0.9), t0 + dur);
  filter.Q.value = cutoff > 0 ? cutoff : 6;
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain, 0.004, dur);
  const panner = makePanner(ctx, pan);
  source.connect(filter);
  filter.connect(amp);
  amp.connect(panner);
  panner.connect(dest);
  source.start(t0);
  source.stop(t0 + dur + 0.05);
  // A quiet sine body keeps the pluck pitched instead of purely percussive.
  tone(ctx, dest, { t0, freq, dur: dur * 0.7, type: 'sine', gain: gain * 0.5, attack: 0.005, decay: dur * 0.7, pan });
}

function kick(ctx, dest, t0, gain = 0.9) {
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(160, t0);
  osc.frequency.exponentialRampToValueAtTime(38, t0 + 0.28);
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain, 0.004, 0.42);
  osc.connect(amp);
  amp.connect(dest);
  osc.start(t0);
  osc.stop(t0 + 0.6);
}

function snare(ctx, dest, t0, gain = 0.34, cache, rnd) {
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, 0.3, rnd, cache);
  const filter = ctx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = 1400;
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain, 0.002, 0.19);
  source.connect(filter);
  filter.connect(amp);
  amp.connect(dest);
  source.start(t0);
  source.stop(t0 + 0.35);
  tone(ctx, dest, { t0, freq: 196, dur: 0.12, type: 'triangle', gain: gain * 0.5, attack: 0.002, decay: 0.12 });
}

function hat(ctx, dest, t0, gain = 0.12, cache, rnd, open = false) {
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, 0.4, rnd, cache);
  const filter = ctx.createBiquadFilter();
  filter.type = 'highpass';
  filter.frequency.value = open ? 6200 : 8200;
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain, 0.001, open ? 0.28 : 0.045);
  const panner = makePanner(ctx, 0.25);
  source.connect(filter);
  filter.connect(amp);
  amp.connect(panner);
  panner.connect(dest);
  source.start(t0);
  source.stop(t0 + 0.45);
}

/** Deep sub drone: the bed the entire film sits on. */
function sub(ctx, dest, t0, dur, gain = 0.22, freq = 36) {
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.linearRampToValueAtTime(gain, t0 + 2.5);
  amp.gain.setValueAtTime(gain, t0 + Math.max(2.5, dur - 3));
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + 0.4);
  const osc = ctx.createOscillator();
  osc.type = 'sine';
  osc.frequency.value = freq;
  const wobble = ctx.createOscillator();
  wobble.type = 'sine';
  wobble.frequency.value = 0.09;
  const wobbleGain = ctx.createGain();
  wobbleGain.gain.value = 1.6;
  wobble.connect(wobbleGain);
  wobbleGain.connect(osc.frequency);
  osc.connect(amp);
  amp.connect(dest);
  osc.start(t0);
  wobble.start(t0);
  osc.stop(t0 + dur + 0.6);
  wobble.stop(t0 + dur + 0.6);
}

/** Rising noise + saw sweep used to build tension before every drop. */
function riser(ctx, dest, t0, dur, gain = 0.3, cache, rnd) {
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, Math.max(0.5, dur), rnd, cache);
  source.loop = true;
  const band = ctx.createBiquadFilter();
  band.type = 'bandpass';
  band.Q.value = 2.2;
  band.frequency.setValueAtTime(220, t0);
  band.frequency.exponentialRampToValueAtTime(9000, t0 + dur);
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.exponentialRampToValueAtTime(gain, t0 + dur);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + 0.25);
  source.connect(band);
  band.connect(amp);
  amp.connect(dest);
  source.start(t0);
  source.stop(t0 + dur + 0.3);
  tone(ctx, dest, { t0, freq: 110, glideTo: 1760, dur, type: 'sawtooth', gain: gain * 0.22, attack: dur * 0.9, decay: 0.25, cutoff: 4200, q: 3 });
}

/** The drop: sub impact + noise crack + reverse-ish swell tail. */
function impact(ctx, dest, t0, gain = 1.0, cache, rnd) {
  kick(ctx, dest, t0, gain);
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, 1.6, rnd, cache);
  const filter = ctx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.setValueAtTime(5200, t0);
  filter.frequency.exponentialRampToValueAtTime(180, t0 + 1.4);
  const amp = ctx.createGain();
  shape(amp.gain, t0, gain * 0.55, 0.002, 1.5);
  source.connect(filter);
  filter.connect(amp);
  amp.connect(dest);
  source.start(t0);
  source.stop(t0 + 1.7);
  tone(ctx, dest, { t0, freq: 92, glideTo: 41, dur: 1.8, type: 'sine', gain: gain * 0.5, attack: 0.005, decay: 1.8 });
}

/** Panned band-passed noise sweep — transitions and camera moves. */
function whoosh(ctx, dest, t0, dur = 0.9, gain = 0.26, cache, rnd, from = -0.9, to = 0.9) {
  const source = ctx.createBufferSource();
  source.buffer = noiseBuffer(ctx, Math.max(0.6, dur), rnd, cache);
  source.loop = true;
  const band = ctx.createBiquadFilter();
  band.type = 'bandpass';
  band.Q.value = 1.1;
  band.frequency.setValueAtTime(380, t0);
  band.frequency.exponentialRampToValueAtTime(3200, t0 + dur * 0.55);
  band.frequency.exponentialRampToValueAtTime(300, t0 + dur);
  const amp = ctx.createGain();
  amp.gain.setValueAtTime(0.0001, t0);
  amp.gain.linearRampToValueAtTime(gain, t0 + dur * 0.35);
  amp.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  const panner = ctx.createStereoPanner();
  panner.pan.setValueAtTime(from, t0);
  panner.pan.linearRampToValueAtTime(to, t0 + dur);
  source.connect(band);
  band.connect(amp);
  amp.connect(panner);
  panner.connect(dest);
  source.start(t0);
  source.stop(t0 + dur + 0.1);
}

/** Glassy high cluster used for the logo reveal. */
function shimmer(ctx, dest, t0, dur, gain = 0.12, pan = 0) {
  const root = noteFreq('a5');
  [1, 1.5, 2, 3].forEach((ratio, index) => {
    tone(ctx, dest, {
      t0: t0 + index * 0.06,
      freq: root * ratio,
      dur,
      type: 'sine',
      gain: gain / (index + 1.4),
      attack: 0.35 + index * 0.08,
      decay: dur,
      pan: pan + (index % 2 === 0 ? 0.2 : -0.2)
    });
  });
}

const VOICES = { tone, pad, pluck, kick, snare, hat, sub, riser, impact, whoosh, shimmer, noiseBuffer, makePanner, shape };

export { VOICES };
